import json

def solve_v2(input_grid):
    """
    Alternative hypothesis:
    A 3 becomes 1 if it's in a 3-cluster that's adjacent to at least one 2.
    But the cluster might be defined as a connected component of 3s (including diagonals?).
    """
    rows = len(input_grid)
    cols = len(input_grid[0])
    result = [[input_grid[r][c] for c in range(cols)] for r in range(rows)]

    # Use BFS to find connected 3-clusters
    visited = [[False] * cols for _ in range(rows)]
    clusters = []

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and input_grid[nr][nc] == 3:
                    neighbors.append((nr, nc))
        return neighbors

    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 3 and not visited[r][c]:
                cluster = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop()
                    cluster.append((cr, cc))
                    for nr, nc in get_neighbors(cr, cc):
                        if not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                clusters.append(cluster)

    # Check if any 2 is adjacent to each cluster
    for cluster in clusters:
        has_adjacent_two = False
        for r, c in cluster:
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and input_grid[nr][nc] == 2:
                        has_adjacent_two = True
                        break
                if has_adjacent_two:
                    break
            if has_adjacent_two:
                break
        if has_adjacent_two:
            for r, c in cluster:
                result[r][c] = 1

    return result

